  $trinjson${"slug": "translation-and-interpretation", "title": "Translation and Interpretation", "description": "Students analyze translation and interpreting tasks by purpose, audience, ethics, genre, domain, and risk; produce Spanish-English translations that control register, grammar, terminology, style, and cultural context; apply terminology research, corpora, CAT/MT literacy, and revision workflows; perform introductory consecutive, sight, simultaneous, and remote interpreting with appropriate protocols and reflection; and assemble a professional portfolio of polished translations, interpreting evidence, revision notes, and decision-making commentary.", "topics": [{"id": "f69a287e-55ce-4cc0-a6ed-3c5390cbd144", "type": "topic", "title": "Translation Theory, Ethics, and Professional Roles", "description": "Introduces translation and interpreting as situated professional practices shaped by purpose, audience, ethics, power, and accountability.", "children": [{"id": "0beacd29-6af4-45e5-ab86-9ec6383b4315", "type": "subtopic", "title": "Translation as mediated communication", "children": [{"id": "f470c09c-62d8-4ba1-83ee-de65a30ef3df", "type": "concept", "title": "Source text, target text, skopos, brief, and audience"}, {"id": "2a6c3de7-fd18-4e61-8b8a-496be5464540", "type": "concept", "title": "Translator visibility, agency, and accountability"}, {"id": "46592710-ccd2-41b7-bf17-21860189a8cb", "type": "concept", "title": "Meaning, form, function, and cultural context"}], "description": "Students begin by seeing translation and interpreting as purposeful communication, not word substitution."}, {"id": "7017f629-d89c-4206-bdb6-5c6d5cf10db5", "type": "subtopic", "title": "Ethics and professional boundaries", "children": [{"id": "2af4ca53-ec9a-45f1-8c42-fa6448a676bf", "type": "concept", "title": "Codes of ethics for translators and interpreters"}, {"id": "7cbf66c1-34f2-4365-b598-332eddea665e", "type": "concept", "title": "Conflicts of interest, advocacy, and intervention"}, {"id": "c9fd1ff8-7c00-4bed-af76-1bef535763f1", "type": "concept", "title": "Confidentiality, informed consent, and sensitive content"}], "description": "This subtopic frames accuracy, impartiality, confidentiality, and role boundaries as practical choices."}, {"id": "04474aba-aa2a-4aa2-b925-0ae5caa7935b", "type": "subtopic", "title": "Professional roles and settings", "children": [{"id": "1118dc78-bf96-4425-bd26-8cb9cd018eb2", "type": "concept", "title": "Freelance, agency, institutional, and community roles"}, {"id": "ab2eecb8-4d34-4469-b5ce-f561aafa8d75", "type": "concept", "title": "Client communication and scope definition"}, {"id": "d59e2e78-dc7f-4347-8797-2539e559e5f5", "type": "concept", "title": "Risk, liability, and documentation"}], "description": "Students distinguish written translation, interpreting, localization, transcreation, and language access work."}]}, {"id": "8cec0eaf-dff4-439c-bc93-0dfe4e7ffa99", "type": "topic", "title": "Equivalence, Register, Audience, and Purpose", "description": "Develops decision-making for meaning, tone, genre, audience, and communicative effect across Spanish and English.", "children": [{"id": "854e85dd-1303-4cbe-aaf7-ea1ac7e20ae1", "type": "subtopic", "title": "Equivalence and shift", "children": [{"id": "494e56ab-5543-4c8e-b3f2-dbe56b3f18bb", "type": "concept", "title": "Semantic, pragmatic, textual, and cultural equivalence"}, {"id": "dd56f4e7-1b14-43ef-8b2b-93e6e2ff5d1d", "type": "concept", "title": "Translation shifts and compensation"}, {"id": "14f367dc-bd4b-41a9-8676-a2d9b7d53907", "type": "concept", "title": "When literal translation works and when it fails"}], "description": "Students learn to choose among literal, functional, dynamic, and communicative solutions."}, {"id": "c59e196a-a725-499b-a349-8926318e686c", "type": "subtopic", "title": "Register and genre", "children": [{"id": "54b3d90c-251b-4988-acc0-34be9ac56a9a", "type": "concept", "title": "Formality, politeness, idiom, slang, and technical style"}, {"id": "5e7be281-97ce-4e32-a2c9-79be91c77310", "type": "concept", "title": "Academic, journalistic, literary, legal, medical, and public-facing genres"}, {"id": "44acf465-3ac1-45b1-bf6a-e5bdf1bd40c1", "type": "concept", "title": "Plain language and readability"}], "description": "Students practice matching tone and genre conventions in both languages."}, {"id": "5cef2d2b-6319-4baa-bc5e-6b6b41c69b05", "type": "subtopic", "title": "Audience and translation brief", "children": [{"id": "cac73a8d-bb03-4bfc-9f86-54ed24b5233d", "type": "concept", "title": "User needs and reading conditions"}, {"id": "886f1e99-327c-4d20-93b8-a52fda1cb0f2", "type": "concept", "title": "Localization constraints and institutional voice"}, {"id": "c55e74f9-0e63-4c7d-8737-bbb71da0edb5", "type": "concept", "title": "Translator notes, caveats, and client-facing rationale"}], "description": "Translation choices become clearer when students define who will use the target text and why."}]}, {"id": "73686701-1f58-4777-82c7-1683783b8ec8", "type": "topic", "title": "Contrastive Grammar and Style", "description": "Builds control over the grammatical, syntactic, punctuation, and stylistic differences that most often affect Spanish-English transfer.", "children": [{"id": "e4964b07-cece-4315-a355-8581258787c1", "type": "subtopic", "title": "Syntax and sentence architecture", "children": [{"id": "26603ed2-8a87-47f2-8e87-7782e5723b86", "type": "concept", "title": "Word order, subordination, coordination, and information flow"}, {"id": "27503be6-33ac-4159-a14f-a6877018ce09", "type": "concept", "title": "Nominalization, passive voice, impersonal constructions, and se"}, {"id": "2ffaaea6-f31f-4503-bafe-ac6916c2b779", "type": "concept", "title": "Long Spanish sentences and English concision"}], "description": "Students address structural differences that create awkward or inaccurate translations."}, {"id": "5121d4fe-6b88-481c-b420-34f19c853dbc", "type": "subtopic", "title": "Tense, aspect, mood, and modality",