-46bc-8c8f-074e56704e87", "type": "subtopic", "title": "Corpora and parallel texts", "children": [{"id": "52468f0f-4981-4138-964d-e7b8358fb21f", "type": "concept", "title": "Comparable and parallel corpora"}, {"id": "c04d65e7-fe85-49c2-94e2-9a389835850a", "type": "concept", "title": "Concordance searching and pattern recognition"}, {"id": "f9ab56db-ffd3-4fe7-8e6c-8aa92b0a0497", "type": "concept", "title": "Source reliability and context checking"}], "description": "This subtopic teaches evidence-based translation choices rather than dictionary dependence."}, {"id": "acc121d2-bb5b-414f-95eb-55cd561c136f", "type": "subtopic", "title": "CAT, MT, and AI literacy", "children": [{"id": "fb2f135c-3c82-4f3d-9d72-38101d831868", "type": "concept", "title": "Translation memory and alignment"}, {"id": "9953fe3c-1c54-476b-9946-deb2bed8f12b", "type": "concept", "title": "Machine translation post-editing"}, {"id": "bdef652f-da84-4f4c-98fd-1567ab5b8ef3", "type": "concept", "title": "Confidentiality, bias, hallucination, and disclosure"}], "description": "Students use technology while maintaining human judgment and ethical responsibility."}]}, {"id": "ced71d29-6abf-4c8b-908f-0515a9b53e23", "type": "topic", "title": "Literary and Humanistic Translation", "description": "Explores voice, rhythm, imagery, cultural references, dialogue, poetry, narrative, and translator visibility in creative texts.", "children": [{"id": "4d5beb7c-afe5-4c19-8310-baad9b2343e0", "type": "subtopic", "title": "Voice, style, and rhythm", "children": [{"id": "b1ca5e31-4bcb-47fb-87b6-5ca9097f9a80", "type": "concept", "title": "Narrative voice, focalization, and tone"}, {"id": "8f26f1bf-f580-4e07-b8ce-6a3b63cf26f9", "type": "concept", "title": "Syntax, cadence, repetition, and sound"}, {"id": "b834051a-c9f4-4fc2-ab21-976eee11de3c", "type": "concept", "title": "Dialogue, dialect, and sociolect"}], "description": "Students practice carrying literary effects across languages without flattening the text."}, {"id": "7c5735a4-bd3d-4294-a35c-075cd7452d7b", "type": "subtopic", "title": "Poetry, imagery, and figurative language", "children": [{"id": "d1be176b-9037-4ae3-aaa8-5fa869312901", "type": "concept", "title": "Metaphor, wordplay, ambiguity, and allusion"}, {"id": "a0679127-fa70-47c0-b1fc-87b92e83bccd", "type": "concept", "title": "Meter, rhyme, line breaks, and visual form"}, {"id": "3a8aeb5a-ad9b-49f5-a6a9-6e83f8142eef", "type": "concept", "title": "Compensation and translator commentary"}], "description": "This subtopic trains students to make principled creative tradeoffs."}, {"id": "59ef736d-d383-4dfc-ab06-64457a6cec9f", "type": "subtopic", "title": "Cultural references and paratexts", "children": [{"id": "14fb0636-d3ca-4342-8eb5-f3f854fcb005", "type": "concept", "title": "Names, food, history, geography, and intertexts"}, {"id": "5e088630-d502-420c-88e8-8e96489c49f4", "type": "concept", "title": "Footnotes, glosses, prefaces, and unobtrusive context"}, {"id": "43212281-c4d8-4b61-ae77-e36703282347", "type": "concept", "title": "Ethics of translating marginalized voices"}], "description": "Students decide how to handle unfamiliar cultural content without overexplaining."}]}, {"id": "e99ca2a5-c8ee-4047-a797-b32c53be43ed", "type": "topic", "title": "Legal, Medical, and Technical Translation", "description": "Introduces specialized translation workflows, domain research, controlled terminology, risk, confidentiality, and audience-specific accuracy.", "children": [{"id": "57b69d99-0efb-41f6-8cc1-5852f4981b3f", "type": "subtopic", "title": "Legal translation", "children": [{"id": "47c91cd4-f877-4ec2-b8ba-4e80e69022cc", "type": "concept", "title": "Contracts, certificates, court documents, and immigration materials"}, {"id": "bc8da9e9-16dd-4ddd-aca0-12b5d0b07a3c", "type": "concept", "title": "False friends, formulaic phrasing, and legal systems"}, {"id": "19e3761b-236f-4056-87ae-25e37bcc2d2f", "type": "concept", "title": "Certification, notarization, and translator declarations"}], "description": "Students learn why legal language requires precision, jurisdictional awareness, and risk control."}, {"id": "fbab676c-60e3-47e0-b17c-1dfc94a4d20c", "type": "subtopic", "title": "Medical and public-health translation", "children": [{"id": "3710f50d-f343-417b-b1e1-32f982ab9f9b", "type": "concept", "title": "Consent forms, discharge instructions, patient education, and medication language"}, {"id": "24261bd3-3716-4aa7-8583-bfc751e6dd5b", "type": "concept", "title": "Plain language, readability, and cultural mediation"}, {"id": "1847319a-0784-43f7-90c6-de27fb4e398f", "type": "concept", "title": "Confidentiality and high-stakes error prevention"}], "description": "This section links terminology precision to patient safety and health literacy."}, {"id": "3a242bc7-b645-422f-8dd7-5b9067093a78", "type": "subtopic", "title": "Technical and scientific translation", "children": [{"id": "5283a156-f8a2-466f-b489-027e0af01249", "type": "concept", "title": "Manuals, specifications, reports, and safety instructions"}, {"id": "d3ff4a37-d735-45aa-bc7d-5478eb3fb6c5", "type": "concept", "title": "Units, numbers, diagrams, warnings, and controlled terminology"}, {"id": "a6812169-4aba-431a-b1fd-8bb594ba8291", "type": "concept", "title": "Subject-matter research and revision loops"}], "description": "Students practice translating procedures and specialized information for defined users."}]}, {"id": "d9aee8a8-3e32-435a-bc12-8a534547e1d0", "type": "topic", "title": "Localization, Transcreation, and Multimodal Translation", "description": "Covers adaptation for software, websites, audiovisual media, marketing, accessibility, subtitles, captions, and culturally embedded user experience.", "children": [{"id": "58498108-8514-429a-8ce4-6c41e84c0441", "type": "subtopic", "title": "Localization workflows", "children": [{"id": "fad36044-2748-465e-8ae4-aa2e5ef65dee", "type": "concept", "title": "Strings, variables, UI constraints, and context"}, {"id": "a60f95e2-3244-4815-b8c0-97