update public.learning_paths
set
  title = 'Translation and Interpretation',
  goal = 'Translation and Interpretation',
  summary = 'Students analyze translation and interpreting tasks by purpose, audience, ethics, genre, domain, and risk; produce Spanish-English translations that control register, grammar, terminology, style, and cultural context; apply terminology research, corpora, CAT/MT literacy, and revision workflows; perform introductory consecutive, sight, simultaneous, and remote interpreting with appropriate protocols and reflection; and assemble a professional portfolio of polished translations, interpreting evidence, revision notes, and decision-making commentary.',
  data = $trinjson${"slug": "translation-and-interpretation", "title": "Translation and Interpretation", "description": "Students analyze translation and interpreting tasks by purpose, audience, ethics, genre, domain, and risk; produce Spanish-English translations that control register, grammar, terminology, style, and cultural context; apply terminology research, corpora, CAT/MT literacy, and revision workflows; perform introductory consecutive, sight, simultaneous, and remote interpreting with appropriate protocols and reflection; and assemble a professional portfolio of polished translations, interpreting evidence, revision notes, and decision-making commentary.", "topics": [{"id": "f69a287e-55ce-4cc0-a6ed-3c5390cbd144", "type": "topic", "title": "Translation Theory, Ethics, and Professional Roles", "description": "Introduces translation and interpreting as situated professional practices shaped by purpose, audience, ethics, power, and accountability.", "children": [{"id": "0beacd29-6af4-45e5-ab86-9ec6383b4315", "type": "subtopic", "title": "Translation as mediated communication", "children": [{"id": "f470c09c-62d8-4ba1-83ee-de65a30ef3df", "type": "concept", "title": "Source text, target text, skopos, brief, and audience"}, {"id": "2a6c3de7-fd18-4e61-8b8a-496be5464540", "type": "concept", "title": "Translator visibility, agency, and accountability"}, {"id": "46592710-ccd2-41b7-bf17-21860189a8cb", "type": "concept", "title": "Meaning, form, function, and cultural context"}], "description": "Students begin by seeing translation and interpreting as purposeful communication, not word substitution."}, {"id": "7017f629-d89c-4206-bdb6-5c6d5cf10db5", "type": "subtopic", "title": "Ethics and professional boundaries", "children": [{"id": "2af4ca53-ec9a-45f1-8c42-fa6448a676bf", "type": "concept", "title": "Codes of ethics for translators and interpreters"}, {"id": "7cbf66c1-34f2-4365-b598-332eddea665e", "type": "concept", "title": "Conflicts of interest, advocacy, and intervention"}, {"id": "c9fd1ff8-7c00-4bed-af76-1bef535763f1", "type": "concept", "title": "Confidentiality, informed consent, and sensitive content"}], "description": "This subtopic frames accuracy, impartiality, confidentiality, and role boundaries as practical choices."}, {"id": "04474aba-aa2a-4aa2-b925-0ae5caa7935b", "type": "subtopic", "title": "Professional roles and settings", "children": [{"id": "1118dc78-bf96-4425-bd26-8cb9cd018eb2", "type": "concept", "title": "Freelance, agency, institutional, and community roles"}, {"id": "ab2eecb8-4d34-4469-b5ce-f561aafa8d75", "type": "concept", "title": "Client communication and scope definition"}, {"id": "d59e2e78-dc7f-4347-8797-2539e559e5f5", "type": "concept", "title": "Risk, liability, and documentation"}], "description": "Students distinguish written translation, interpreting, localization, transcreation, and language access work."}]}, {"id": "8cec0eaf-dff4-439c-bc93-0dfe4e7ffa99", "type": "topic", "title": "Equivalence, Register, Audience, and Purpose", "description": "Develops decision-making for meaning, tone, genre, audience, and communicative effect across Spanish and English.", "children": [{"id": "854e85dd-1303-4cbe-aaf7-ea1ac7e20ae1", "type": "subtopic", "title": "Equivalence and shift", "children": [{"id": "494e56ab-5543-4c8e-b3f2-dbe56b3f18bb", "type": "concept", "title": "Semantic, pragmatic, textual, and cultural equivalence"}, {"id": "dd56f4e7-1b14-43ef-8b2b-93e6e2ff5d1d", "type": "concept", "title": "Translation shifts and compensation"}, {"id": "14f367dc-bd4b-41a9-8676-a2d9b7d53907", "type": "concept", "title": "When literal translation works and when it fails"}], "description": "Students learn to choose among literal, functional, dynamic, and communicative solutions."}, {"id": "c59e196a-a725-499b-a349-8926318e686c", "type": "subtopic", "title": "Register and genre", "children": [{"id": "54b3d90c-251b-4988-acc0-34be9ac56a9a", "type": "concept", "title": "Formality, politeness, idiom, slang, and technical style"}, {"id": "5e7be281-97ce-4e32-a2c9-79be91c77310", "type": "concept", "title": "Academic, journalistic, literary, legal, medical, and public-facing genres"}, {"id": "44acf465-3ac1-45b1-bf6a-e5bdf1bd40c1", "type": "concept", "title": "Plain language and readability"}], "description": "Students practice matching tone and genre conventions in both languages."}, {"id": "5cef2d2b-6319-4baa-bc5e-6b6b41c69b05", "type": "subtopic", "title": "Audience and translation brief", "children": [{"id": "cac73a8d-bb03-4bfc-9f86-54ed24b5233d", "type": "concept", "title": "User needs and reading conditions"}, {"id": "886f1e99-327c-4d20-93b8-a52fda1cb0f2", "type": "concept", "title": "Localization constraints and institutional voice"}, {"id": "c55e74f9-0e63-4c7d-8737-bbb71da0edb5", "type": "concept", "title": "Translator notes, caveats, and client-facing rationale"}], "description": "Translation choices become clearer when students define who will use the target text and why."}]}, {"id": "73686701-1f58-4777-82c7-1683783b8ec8", "type": "topic", "title": "Contrastive Grammar and Style", "description": "Builds control over the grammatical, syntactic, punctuation, and stylistic differences that most often affect Spanish-English transfer.", "children": [{"id": "e4964b07-cece-4315-a355-8581258787c1", "type": "subtopic", "title": "Syntax and sentence architecture", "children": [{"id": "26603ed2-8a87-47f2-8e87-7782e5723b86", "type": "concept", "title": "Word order, subordination, coordination, and information flow"}, {"id": "27503be6-33ac-4159-a14f-a6877018ce09", "type": "concept", "title": "Nominalization, passive voice, impersonal constructions, and se"}, {"id": "2ffaaea6-f31f-4503-bafe-ac6916c2b779", "type": "concept", "title": "Long Spanish sentences and English concision"}], "description": "Students address structural differences that create awkward or inaccurate translations."}, {"id": "5121d4fe-6b88-481c-b420-34f19c853dbc", "type": "subtopic", "title": "Tense, aspect, mood, and modality", "children": [{"id": "c131d68d-584d-47f1-a7d1-3711ffdb32f1", "type": "concept", "title": "Preterite, imperfect, perfect, and progressive forms"}, {"id": "5de243b1-b42b-45f3-bd0e-455a8682da63", "type": "concept", "title": "Subjunctive, conditional, obligation, probability, and hedging"}, {"id": "943cb48f-35f5-4d25-b21c-1902f6bbafdc", "type": "concept", "title": "Modals, evidentiality, and stance"}], "description": "This subtopic targets high-impact grammar choices across Spanish and English."}, {"id": "a45b6db8-23ba-4677-8e15-a7a2d6cc170c", "type": "subtopic", "title": "Lexis, punctuation, and style", "children": [{"id": "af54bc2c-cf26-457b-8dd9-cb5e9498982c", "type": "concept", "title": "False cognates, collocations, and idioms"}, {"id": "93ea1631-45c2-410c-ad85-3c332848b515", "type": "concept", "title": "Capitalization, quotation marks, commas, and numbers"}, {"id": "312a1405-87c7-4544-b529-6944bbaf4928", "type": "concept", "title": "Inclusive language, regional usage, and style guides"}], "description": "Students refine details that affect credibility and readability."}]}, {"id": "3a409659-33df-459f-a76e-2e1a06391160", "type": "topic", "title": "Terminology, Corpora, and Translation Technology", "description": "Teaches terminology management, parallel-text research, corpora, CAT tools, machine translation literacy, and responsible AI use.", "children": [{"id": "fcd912fc-7a7d-4506-801a-e9a51e90055a", "type": "subtopic", "title": "Terminology management", "children": [{"id": "c5291cbe-326a-4c58-a327-ab3008b0058c", "type": "concept", "title": "Termbases, glossaries, definitions, contexts, and sources"}, {"id": "02d70969-8cb1-4688-ae1d-e743e032558e", "type": "concept", "title": "Domain validation and subject-matter consultation"}, {"id": "ec5a8e27-cbfd-4f71-bac2-57a1734b84c3", "type": "concept", "title": "Acronyms, proper nouns, and controlled language"}], "description": "Students learn to research, define, store, and reuse terms consistently."}, {"id": "e5850568-5827-46bc-8c8f-074e56704e87", "type": "subtopic", "title": "Corpora and parallel texts", "children": [{"id": "52468f0f-4981-4138-964d-e7b8358fb21f", "type": "concept", "title": "Comparable and parallel corpora"}, {"id": "c04d65e7-fe85-49c2-94e2-9a389835850a", "type": "concept", "title": "Concordance searching and pattern recognition"}, {"id": "f9ab56db-ffd3-4fe7-8e6c-8aa92b0a0497", "type": "concept", "title": "Source reliability and context checking"}], "description": "This subtopic teaches evidence-based translation choices rather than dictionary dependence."}, {"id": "acc121d2-bb5b-414f-95eb-55cd561c136f", "type": "subtopic", "title": "CAT, MT, and AI literacy", "children": [{"id": "fb2f135c-3c82-4f3d-9d72-38101d831868", "type": "concept", "title": "Translation memory and alignment"}, {"id": "9953fe3c-1c54-476b-9946-deb2bed8f12b", "type": "concept", "title": "Machine translation post-editing"}, {"id": "bdef652f-da84-4f4c-98fd-1567ab5b8ef3", "type": "concept", "title": "Confidentiality, bias, hallucination, and disclosure"}], "description": "Students use technology while maintaining human judgment and ethical responsibility."}]}, {"id": "ced71d29-6abf-4c8b-908f-0515a9b53e23", "type": "topic", "title": "Literary and Humanistic Translation", "description": "Explores voice, rhythm, imagery, cultural references, dialogue, poetry, narrative, and translator visibility in creative texts.", "children": [{"id": "4d5beb7c-afe5-4c19-8310-baad9b2343e0", "type": "subtopic", "title": "Voice, style, and rhythm", "children": [{"id": "b1ca5e31-4bcb-47fb-87b6-5ca9097f9a80", "type": "concept", "title": "Narrative voice, focalization, and tone"}, {"id": "8f26f1bf-f580-4e07-b8ce-6a3b63cf26f9", "type": "concept", "title": "Syntax, cadence, repetition, and sound"}, {"id": "b834051a-c9f4-4fc2-ab21-976eee11de3c", "type": "concept", "title": "Dialogue, dialect, and sociolect"}], "description": "Students practice carrying literary effects across languages without flattening the text."}, {"id": "7c5735a4-bd3d-4294-a35c-075cd7452d7b", "type": "subtopic", "title": "Poetry, imagery, and figurative language", "children": [{"id": "d1be176b-9037-4ae3-aaa8-5fa869312901", "type": "concept", "title": "Metaphor, wordplay, ambiguity, and allusion"}, {"id": "a0679127-fa70-47c0-b1fc-87b92e83bccd", "type": "concept", "title": "Meter, rhyme, line breaks, and visual form"}, {"id": "3a8aeb5a-ad9b-49f5-a6a9-6e83f8142eef", "type": "concept", "title": "Compensation and translator commentary"}], "description": "This subtopic trains students to make principled creative tradeoffs."}, {"id": "59ef736d-d383-4dfc-ab06-64457a6cec9f", "type": "subtopic", "title": "Cultural references and paratexts", "children": [{"id": "14fb0636-d3ca-4342-8eb5-f3f854fcb005", "type": "concept", "title": "Names, food, history, geography, and intertexts"}, {"id": "5e088630-d502-420c-88e8-8e96489c49f4", "type": "concept", "title": "Footnotes, glosses, prefaces, and unobtrusive context"}, {"id": "43212281-c4d8-4b61-ae77-e36703282347", "type": "concept", "title": "Ethics of translating marginalized voices"}], "description": "Students decide how to handle unfamiliar cultural content without overexplaining."}]}, {"id": "e99ca2a5-c8ee-4047-a797-b32c53be43ed", "type": "topic", "title": "Legal, Medical, and Technical Translation", "description": "Introduces specialized translation workflows, domain research, controlled terminology, risk, confidentiality, and audience-specific accuracy.", "children": [{"id": "57b69d99-0efb-41f6-8cc1-5852f4981b3f", "type": "subtopic", "title": "Legal translation", "children": [{"id": "47c91cd4-f877-4ec2-b8ba-4e80e69022cc", "type": "concept", "title": "Contracts, certificates, court documents, and immigration materials"}, {"id": "bc8da9e9-16dd-4ddd-aca0-12b5d0b07a3c", "type": "concept", "title": "False friends, formulaic phrasing, and legal systems"}, {"id": "19e3761b-236f-4056-87ae-25e37bcc2d2f", "type": "concept", "title": "Certification, notarization, and translator declarations"}], "description": "Students learn why legal language requires precision, jurisdictional awareness, and risk control."}, {"id": "fbab676c-60e3-47e0-b17c-1dfc94a4d20c", "type": "subtopic", "title": "Medical and public-health translation", "children": [{"id": "3710f50d-f343-417b-b1e1-32f982ab9f9b", "type": "concept", "title": "Consent forms, discharge instructions, patient education, and medication language"}, {"id": "24261bd3-3716-4aa7-8583-bfc751e6dd5b", "type": "concept", "title": "Plain language, readability, and cultural mediation"}, {"id": "1847319a-0784-43f7-90c6-de27fb4e398f", "type": "concept", "title": "Confidentiality and high-stakes error prevention"}], "description": "This section links terminology precision to patient safety and health literacy."}, {"id": "3a242bc7-b645-422f-8dd7-5b9067093a78", "type": "subtopic", "title": "Technical and scientific translation", "children": [{"id": "5283a156-f8a2-466f-b489-027e0af01249", "type": "concept", "title": "Manuals, specifications, reports, and safety instructions"}, {"id": "d3ff4a37-d735-45aa-bc7d-5478eb3fb6c5", "type": "concept", "title": "Units, numbers, diagrams, warnings, and controlled terminology"}, {"id": "a6812169-4aba-431a-b1fd-8bb594ba8291", "type": "concept", "title": "Subject-matter research and revision loops"}], "description": "Students practice translating procedures and specialized information for defined users."}]}, {"id": "d9aee8a8-3e32-435a-bc12-8a534547e1d0", "type": "topic", "title": "Localization, Transcreation, and Multimodal Translation", "description": "Covers adaptation for software, websites, audiovisual media, marketing, accessibility, subtitles, captions, and culturally embedded user experience.", "children": [{"id": "58498108-8514-429a-8ce4-6c41e84c0441", "type": "subtopic", "title": "Localization workflows", "children": [{"id": "fad36044-2748-465e-8ae4-aa2e5ef65dee", "type": "concept", "title": "Strings, variables, UI constraints, and context"}, {"id": "a60f95e2-3244-4815-